const item = $input.first().json;
const raw = item.output || item.text || item;
let data = null;

if (typeof raw === "object" && raw !== null) {
  data = raw;
} else if (typeof raw === "string") {
  let cleaned = raw.trim().replace(/^\`\`\`(?:json)?\s*/i, "").replace(/\s*\`\`\`$/i, "").trim();
  try {
    data = JSON.parse(cleaned);
  } catch (e1) {
    const match = cleaned.match(/\{[\s\S]*/);
    if (match) {
      let candidate = match[0];
      const qm = candidate.match(/(?<!\\)"/g) || [];
      if (qm.length % 2 !== 0) candidate += '"';
      let ob = (candidate.match(/\{/g) || []).length;
      let cb = (candidate.match(/\}/g) || []).length;
      let obk = (candidate.match(/\[/g) || []).length;
      let cbk = (candidate.match(/\]/g) || []).length;
      while (cbk < obk) { candidate += ']'; cbk++; }
      while (cb < ob) { candidate += '}'; cb++; }
      try {
        data = JSON.parse(candidate);
      } catch (e2) {
        candidate = match[0].replace(/,\s*"[^"]*"\s*:\s*"?[^"}]*$/, "");
        let ob2 = (candidate.match(/\{/g) || []).length;
        let cb2 = (candidate.match(/\}/g) || []).length;
        let obk2 = (candidate.match(/\[/g) || []).length;
        let cbk2 = (candidate.match(/\]/g) || []).length;
        while (cbk2 < obk2) { candidate += ']'; cbk2++; }
        while (cb2 < ob2) { candidate += '}'; cb2++; }
        try { data = JSON.parse(candidate); } catch (e3) { data = {}; }
      }
    } else {
      data = {};
    }
  }
}

const content = (data && data.output) ? data.output : (data || {});
return [{ json: { output: content } }];
